CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated, service_role;
CREATE TABLE public.bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_key uuid NOT NULL UNIQUE, name text NOT NULL CHECK(length(name) BETWEEN 2 AND 80), phone text NOT NULL CHECK(length(phone) BETWEEN 10 AND 15), service text NOT NULL CHECK(length(service) BETWEEN 1 AND 100), vehicle text NOT NULL CHECK(length(vehicle) BETWEEN 1 AND 80), scheduled_date date NOT NULL, scheduled_time time NOT NULL, origin text NOT NULL CHECK(length(origin) BETWEEN 1 AND 120), destination text NOT NULL CHECK(length(destination) BETWEEN 1 AND 120), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=400), internal_notes text NOT NULL DEFAULT '' CHECK(length(internal_notes)<=2000), source text NOT NULL DEFAULT 'site' CHECK(source IN ('site','manual')), status text NOT NULL DEFAULT 'novo' CHECK(status IN ('novo','confirmado','em_atendimento','concluido','cancelado')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.bookings TO authenticated;
GRANT ALL ON public.bookings TO service_role;
ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read ON public.bookings FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_insert ON public.bookings FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_update ON public.bookings FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE INDEX bookings_created_idx ON public.bookings(created_at DESC);
CREATE INDEX bookings_schedule_idx ON public.bookings(scheduled_date,scheduled_time);
CREATE FUNCTION public.touch_booking() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END $$;
CREATE TRIGGER bookings_updated BEFORE UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION public.touch_booking();